import{b as s,I as a,g as n,j as t}from"./chunks/framework.CrSplIeq.js";const h=JSON.parse('{"title":"Preferences","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-preferences.md","filePath":"guide/api-preferences.md"}'),r={name:"guide/api-preferences.md"};function o(p,e,c,i,l,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="preferences" tabindex="-1">Preferences <a class="header-anchor" href="#preferences" aria-label="Permalink to &quot;Preferences&quot;">​</a></h1><p>Preferences store per-user UI configuration for a named resource (for example table column layouts). The list for a resource merges <strong>system templates</strong> (<code>locked: true</code>) with the authenticated user&#39;s own rows.</p><p><code>:resource</code> is the resource <strong>name</strong> (not ID).</p><h2 id="list-preferences" tabindex="-1">List Preferences <a class="header-anchor" href="#list-preferences" aria-label="Permalink to &quot;List Preferences&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /gatelin/preferences/:resource</span></span>
<span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span></code></pre></div><p><strong>Response (200 OK):</strong> rows include system templates and the caller&#39;s preferences, each with <code>isActive</code> from the selection table.</p><h2 id="create-preferences" tabindex="-1">Create Preferences <a class="header-anchor" href="#create-preferences" aria-label="Permalink to &quot;Create Preferences&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /gatelin/preferences/:resource</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;rows&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;My layout&quot;,</span></span>
<span class="line"><span>      &quot;conf&quot;: { &quot;columns&quot;: [&quot;id&quot;, &quot;name&quot;] },</span></span>
<span class="line"><span>      &quot;isActive&quot;: true</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Gatelin injects <code>userId</code> and <code>resourceId</code> from the session and the named resource. <strong>Response (201 Created)</strong></p><h2 id="update-preferences" tabindex="-1">Update Preferences <a class="header-anchor" href="#update-preferences" aria-label="Permalink to &quot;Update Preferences&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT /gatelin/preferences/:resource</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;rows&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>      &quot;id&quot;: 12,</span></span>
<span class="line"><span>      &quot;name&quot;: &quot;My layout&quot;,</span></span>
<span class="line"><span>      &quot;conf&quot;: { &quot;columns&quot;: [&quot;id&quot;, &quot;name&quot;, &quot;email&quot;] },</span></span>
<span class="line"><span>      &quot;isActive&quot;: true</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Only rows owned by the caller, unlocked, and belonging to <code>:resource</code> can be updated. Locked system templates cannot be overwritten. <strong>Response (200 OK)</strong></p><h2 id="delete-preference" tabindex="-1">Delete Preference <a class="header-anchor" href="#delete-preference" aria-label="Permalink to &quot;Delete Preference&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /gatelin/preferences/:resource/:id</span></span>
<span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span></code></pre></div><p>Deletes a single preference owned by the authenticated user. <strong>Response (204 No Content)</strong></p><h3 id="preference-fields" tabindex="-1">Preference Fields <a class="header-anchor" href="#preference-fields" aria-label="Permalink to &quot;Preference Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>Preference label (max 60 chars)</td></tr><tr><td><code>conf</code></td><td>JSON configuration object</td></tr><tr><td><code>locked</code></td><td><code>true</code> for system templates (read-only)</td></tr><tr><td><code>isActive</code></td><td>Whether this preference is the active selection for the user</td></tr><tr><td><code>resourceId</code> / <code>resourceName</code></td><td>Resource the preference belongs to</td></tr></tbody></table>`,17)])])}const f=s(r,[["render",o]]);export{h as __pageData,f as default};
